pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool doRevert) public {
        amount = bound(amount, 0, 1 ether);

        Adversary adv = new Adversary(doRevert);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(adv), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Adversary {
    bool public willRevert;
    constructor(bool _willRevert) payable {
        willRevert = _willRevert;
    }
    fallback() external payable {
        if (willRevert) revert("adversary revert");
    }
    receive() external payable {
        if (willRevert) revert("adversary revert");
    }
}
